// Validate the settings, then work out last month and the month before.
const s = $input.first().json;
const problems = [];
const wabaId = String(s.waba_id ?? '').trim();
if (!/^\d{6,20}$/.test(wabaId)) problems.push('waba_id must be the numeric WhatsApp Business Account ID (Meta Business Suite > Settings > Accounts > WhatsApp accounts), not the phone number ID.');
const budget = Number(s.monthly_budget);
if (!Number.isFinite(budget) || budget < 0) problems.push('monthly_budget must be a number in your account currency (0 = no budget check).');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(s.report_email ?? '').trim())) problems.push('report_email must be an email address.');
if (!/^v\d+\.\d+$/.test(String(s.graph_api_version ?? ''))) problems.push('graph_api_version should look like v24.0.');
if (problems.length) throw new Error('Fix the Settings node: ' + problems.join(' '));

// Calendar months in the workflow timezone (Workflow settings > Timezone).
const thisMonth = $now.startOf('month');
const lastMonth = thisMonth.minus({ months: 1 });
const monthBefore = thisMonth.minus({ months: 2 });

return [{
  json: {
    waba_id: wabaId,
    monthly_budget: budget,
    report_email: String(s.report_email).trim(),
    graph_api_version: s.graph_api_version,
    start: Math.floor(monthBefore.toSeconds()),
    end: Math.floor(thisMonth.toSeconds()),
    last_month_start: Math.floor(lastMonth.toSeconds()),
    last_month: lastMonth.toFormat('LLLL yyyy'),
    month_before: monthBefore.toFormat('LLLL yyyy'),
  },
}];

// Price every line Meta returned with the list rate (or volume tier rate) of its market.
const meta = $('Get message volumes from Meta').first().json;
const cfg = $('Check settings and dates').first().json;
const currency = meta.currency;
const rates = $('Read list rates').all().map((i) => i.json);
const tiers = $input.all().map((i) => i.json).filter((t) => t.currency === currency);

// Country (ISO code) -> rate market. Countries without their own market fall under "Other".
const marketOf = {};
for (const r of rates) for (const iso of String(r.iso_codes || '').split(' ').filter(Boolean)) marketOf[iso] = r;
const other = rates.find((r) => r.type === 'other');

// Meta's pricing categories -> rate card columns. Marketing Lite is billed at the marketing rate.
const column = {
  MARKETING: 'marketing', MARKETING_LITE: 'marketing', UTILITY: 'utility',
  AUTHENTICATION: 'authentication', AUTHENTICATION_INTERNATIONAL: 'authentication_international', SERVICE: 'service',
};
const num = (v) => (v === '' || v === null || v === undefined ? null : Number(v));

const points = (meta.pricing_analytics?.data ?? []).flatMap((d) => d.data_points ?? []);
const lines = points.map((p) => {
  const market = marketOf[p.country] ?? other;
  const col = column[p.pricing_category];
  const paid = p.pricing_type === 'REGULAR';
  let rate = paid ? null : 0;
  let note = paid ? '' : 'free';
  if (paid && !col) note = 'category not on the rate card';
  if (paid && col) {
    rate = num(market[col]);
    // Authentication-international only exists in some markets; elsewhere the authentication rate applies.
    if (rate === null && col === 'authentication_international') rate = num(market.authentication);
    // Meta reports the volume tier as "from:to". Above the first tier a lower tier rate applies.
    const tierStart = p.tier ? Number(String(p.tier).split(':')[0]) : 0;
    if (tierStart > 0) {
      const t = tiers.find((x) => x.market === market.market && x.category === col
        && Number(x.tier_from) <= tierStart + 1 && (x.tier_to === '' || Number(x.tier_to) >= tierStart + 1));
      if (t) { rate = Number(t.rate); note = `tier ${p.tier}`; }
    }
    if (rate === null) note = 'no list rate published';
  }
  return {
    month: p.start >= cfg.last_month_start - 3 * 86400 ? 'last' : 'before',
    country: p.country, market: market.market, category: p.pricing_category, pricing_type: p.pricing_type,
    volume: p.volume ?? 0, rate, cost: rate === null ? 0 : rate * (p.volume ?? 0),
    meta_cost: p.cost ?? null, note,
  };
});

return [{ json: {
  currency, effective_date: rates[0]?.effective_date, checked_on: rates[0]?.checked_on,
  more_pages: Boolean(meta.pricing_analytics?.paging?.next), lines,
} }];

// Summarise last month, compare it with the month before and build the email.
const { currency, effective_date, checked_on, more_pages, lines } = $input.first().json;
const cfg = $('Check settings and dates').first().json;
const money = (n) => `${currency} ${n.toFixed(2)}`;
const sum = (arr, f) => arr.reduce((a, x) => a + f(x), 0);

const last = lines.filter((l) => l.month === 'last');
const before = lines.filter((l) => l.month === 'before');
const total = sum(last, (l) => l.cost);
const totalBefore = sum(before, (l) => l.cost);
const paid = last.filter((l) => l.pricing_type === 'REGULAR');
const free = last.filter((l) => l.pricing_type !== 'REGULAR');
const metaCost = last.some((l) => l.meta_cost !== null) ? sum(last, (l) => l.meta_cost ?? 0) : null;
const unpriced = paid.filter((l) => l.rate === null);

const group = (arr, key) => Object.values(arr.reduce((acc, l) => {
  const k = l[key];
  acc[k] ??= { name: k, volume: 0, cost: 0 };
  acc[k].volume += l.volume;
  acc[k].cost += l.cost;
  return acc;
}, {})).sort((a, b) => b.cost - a.cost || b.volume - a.volume);
const label = {
  MARKETING: 'Marketing', MARKETING_LITE: 'Marketing (Lite API)', UTILITY: 'Utility', AUTHENTICATION: 'Authentication',
  AUTHENTICATION_INTERNATIONAL: 'Authentication (international)', SERVICE: 'Service',
};
const byCategory = group(paid, 'category').map((r) => ({ ...r, name: label[r.name] ?? r.name }));
const byCountry = group(paid, 'country').slice(0, 5);

const change = totalBefore > 0 ? ((total - totalBefore) / totalBefore) * 100 : null;
const budget = cfg.monthly_budget;
const overBudget = budget > 0 && total > budget;
const budgetLine = budget > 0
  ? `${money(total)} of your ${money(budget)} budget (${Math.round((total / budget) * 100)}%)`
  : 'No budget set';

const table = (rows) => `<table cellpadding="6" style="border-collapse:collapse">
<tr style="background:#f2f2f2"><th align="left">Name</th><th align="right">Messages</th><th align="right">Cost</th></tr>
${rows.map((r) => `<tr><td>${r.name}</td><td align="right">${r.volume}</td><td align="right">${money(r.cost)}</td></tr>`).join('')}
</table>`;

const notes = [];
if (unpriced.length) notes.push(`${sum(unpriced, (l) => l.volume)} paid messages had no list rate (${[...new Set(unpriced.map((l) => l.category))].join(', ')}) and are not in the total.`);
if (more_pages) notes.push('Meta returned more than one page of data; only the first page is included.');
if (metaCost !== null) notes.push(`Meta's own cost figure for ${cfg.last_month}: ${money(metaCost)} (approximate, as reported by the API).`);

const html = `<h2>WhatsApp Business API cost, ${cfg.last_month}</h2>
${overBudget ? `<p style="color:#b00020"><b>Over budget:</b> ${budgetLine}.</p>` : `<p>${budgetLine}.</p>`}
<p><b>Estimated cost: ${money(total)}</b>${change === null ? '' : ` (${change >= 0 ? '+' : ''}${change.toFixed(0)}% on ${cfg.month_before}: ${money(totalBefore)})`}<br>
Paid messages: ${sum(paid, (l) => l.volume)}. Free messages (customer service window, free entry points): ${sum(free, (l) => l.volume)}.</p>
${paid.length ? `<h3>Per category</h3>${table(byCategory)}<h3>Top countries</h3>${table(byCountry)}` : '<p>No paid messages last month.</p>'}
${notes.length ? `<p>${notes.join('<br>')}</p>` : ''}
<p style="color:#666;font-size:12px">Estimate: message volumes from Meta's pricing analytics for WABA ${cfg.waba_id}, priced at Meta's list rates in ${currency} effective ${effective_date} (rate card checked ${checked_on}), volume tiers included. Excludes VAT and partner fees; Meta's invoice is leading.
Rates: open dataset <a href="https://github.com/tobachat/whatsapp-api-rates">tobachat/whatsapp-api-rates</a> (CC BY 4.0).</p>`;

return [{ json: {
  subject: `${overBudget ? 'Over budget: ' : ''}WhatsApp cost ${cfg.last_month}: ${money(total)}`,
  html,
  over_budget: overBudget,
  total: Number(total.toFixed(4)),
  total_month_before: Number(totalBefore.toFixed(4)),
  currency,
  paid_messages: sum(paid, (l) => l.volume),
  free_messages: sum(free, (l) => l.volume),
} }];

// Turn a failed call into a short explanation with the fix.
const item = $input.first().json;
const err = item.error ?? item;
const raw = `${err.message ?? ''} ${err.description ?? ''}`.trim() || JSON.stringify(err);
// Meta puts its error code in the response body, e.g. "code":190.
const metaCode = Number((raw.match(/code\\?"\s*:\s*(\d+)/) ?? [])[1]);
let fix = 'Open the failed execution in n8n to see which node failed.';
if (metaCode === 190 || /expired/i.test(raw)) fix = 'The Meta access token is invalid or expired. Create a System User token with the whatsapp_business_management permission and update the Header Auth credential.';
else if (metaCode === 100) fix = 'Meta cannot load this WhatsApp Business Account. Check waba_id in the Settings node (the WABA ID, not the phone number ID) and that the System User behind the token has been given access to this WABA.';
else if (metaCode === 10 || metaCode === 200 || /permission/i.test(raw)) fix = 'The token lacks permission. Give the System User the whatsapp_business_management permission and assign the WABA to it.';
else if (/404|githubusercontent/i.test(raw)) fix = 'The rate file could not be downloaded. Check that your account currency is one Meta publishes rates in, or try again later.';
const cfg = $('Check settings and dates').first().json;
return [{ json: {
  subject: `WhatsApp cost report for ${cfg.last_month} failed`,
  html: `<p>The monthly WhatsApp cost report could not be built.</p><p><b>What to do:</b> ${fix}</p><p style="color:#666;font-size:12px">Error: ${raw.slice(0, 600).replace(/</g, '&lt;')}</p>`,
} }];
